int main(){
vector<double>x={1,2,4,5},factor={1,1,2,2},y={2,4,7,9};double mf=0,mx=0,my=0,ff=0,fx=0,fy=0;for(int i=0;i<4;i++){mf+=factor[i]/4;mx+=x[i]/4;my+=y[i]/4;}for(int i=0;i<4;i++){double a=factor[i]-mf;ff+=a*a;fx+=a*(x[i]-mx);fy+=a*(y[i]-my);}double xx=0,xy=0;for(int i=0;i<4;i++){double xr=x[i]-mx-fx/ff*(factor[i]-mf),yr=y[i]-my-fy/ff*(factor[i]-mf);xx+=xr*xr;xy+=xr*yr;}cout<<"partial slope "<<xy/xx<<"\n";
return 0;
}

